-- Hide old unnumbered location rows from user location dropdowns.
-- Run after update_campus_numbered_locations_v62.sql if old names still appear.
UPDATE LOCATIONS
   SET USE_YN = 'N'
 WHERE USE_YN = 'Y'
   AND LOCATION_NAME NOT IN ('1. 대학본관', '2. 보건복지관', '3. 건축디자인관', '4. 대학원', '5. 건축공학실습동', '6. 학생회관', '7. 동명스타디움', '8. 학생복지관', '9. 동명생활관 (2호관)', '10. 중앙도서관', '11. 동명관', '12. 반려동물관', '13. ICT 2관', '14. ICT 3관', '15. ICT 1관', '16. 교수연구동', '17. 국제대학관', '18. 동명공업고등학교', '19. 국제대학 본관', '20. 쉼터(편의점)', '21. 국제산학협력관(학생군사관)', '22. 가온누리(학생휴게점)', '23. 선당', '24. 창의인재관', '25. 분수대', '26. 용마광장', '27. 제1정문', '28. 제2정문', '29. 제3정문', '30. 제1주차장', '31. 제2주차장', '32. 대운동장 1', '33. 대운동장 2', '34. 원형광장', '35. 주차관제소', '36. 종합체육시설', '37. 제3주차장', '38. 제5주차장', '39. 순환버스 정류장', '40. 마지뜨락', '41. 분수대', '42. 학생휴게점(cafe)', '43. 동명생활관 (1호관)', '44. 동명뜰', '45. 체육시설관리동', '46. 그린스타트업타운', '47. 대학동물병원', '48. 창업거점지구')
   AND NOT REGEXP_LIKE(LOCATION_NAME, '^[0-9]+\.');

COMMIT;